(() => {
  const checks=[];
  const check=(name,value)=>{if(!value)checks.push(name)};
  document.body.innerHTML='<div id="a" class="subject"></div><div id="b" class="subject"></div>';
  const a=document.getElementById('a'),b=document.getElementById('b');
  const owner=document.createElement('style');
  owner.textContent='.subject { color:red;display:inline;opacity:0.2 }';document.head.append(owner);
  const sa=getComputedStyle(a),sb=getComputedStyle(b);
  check('initial',sa.opacity==='0.2'&&sb.opacity==='0.2');
  a.style.position='absolute';
  check('computed entries are not shared',sa.display==='block'&&sb.display==='inline');
  owner.sheet.cssRules[0].style.opacity='0.3';check('rule property',sa.opacity==='0.3');
  owner.sheet.cssRules[0].style.cssText='opacity:0.4';check('rule cssText',sa.opacity==='0.4');
  owner.sheet.cssRules[0].selectorText='#b';check('selector mutation',sa.opacity==='1'&&sb.opacity==='0.4');
  owner.sheet.insertRule('#a {opacity:0.5}',1);check('insert rule',sa.opacity==='0.5');
  owner.sheet.deleteRule(1);check('delete rule',sa.opacity==='1');
  owner.textContent='.subject{opacity:0.6}';check('owner text',sa.opacity==='0.6');
  owner.disabled=true;check('disable',sa.opacity==='1');owner.disabled=false;
  owner.remove();check('remove owner',sa.opacity==='1');document.head.append(owner);
  check('reattach owner',sa.opacity==='0.6');
  a.className='other';check('class mutation',sa.opacity==='1');a.className='subject';
  const sheet=new CSSStyleSheet();sheet.replaceSync('#a{opacity:0.7}');document.adoptedStyleSheets=[sheet];
  check('adopt',sa.opacity==='0.7');sheet.replaceSync('#a{opacity:0.8}');check('replace',sa.opacity==='0.8');
  sheet.replaceSync('@media screen { #a {opacity:0.9} }');
  check('nested initial',sa.opacity==='0.9');sheet.cssRules[0].cssRules[0].style.opacity='0.25';
  check('nested mutation',sa.opacity==='0.25');document.adoptedStyleSheets=[];
  check('unadopt',sa.opacity==='0.6');
  check('grouped selectors',Array.from(document.querySelectorAll('#b, .subject, #a'),n=>n.id).join()==='a,b');
  const shadowHost=document.createElement('section');a.after(shadowHost);
  const root=shadowHost.attachShadow({mode:'open'});root.innerHTML='<x-cache-order id="shadow"></x-cache-order>';
  a.innerHTML='<x-cache-order id="before"></x-cache-order>';
  shadowHost.innerHTML='<x-cache-order id="light"></x-cache-order>';
  b.innerHTML='<x-cache-order id="after"></x-cache-order>';
  const order=[];
  customElements.define('x-cache-order',class extends HTMLElement{constructor(){super();order.push(this.id)}});
  check('shadow-including upgrade order',order.join()==='before,shadow,light,after');
  const boxStyle=document.createElement('style');boxStyle.textContent='x-cache-box{display:flex} x-cache-box.hidden-box{display:none} .sized-box{width:123px;height:45px}';document.head.append(boxStyle);
  const container=document.createElement('div');container.style.width='300px';container.innerHTML='<x-cache-box></x-cache-box><x-cache-box class="sized-box"></x-cache-box><x-cache-box class="hidden-box"><div style="height:1000px"></div></x-cache-box>';document.body.append(container);
  const boxes=container.children;
  check('stylesheet auto block width',boxes[0].clientWidth===300&&boxes[0].getBoundingClientRect().width===300);
  check('stylesheet explicit box',boxes[1].clientWidth===123&&boxes[1].clientHeight===45);
  check('stylesheet hidden subtree',boxes[2].getBoundingClientRect().width===0&&boxes[2].getBoundingClientRect().height===0);
  const aspect=document.createElement('div');aspect.style.cssText='width:240px;height:0;padding-top:30px;position:relative';
  aspect.innerHTML='<div style="position:absolute;width:100%;height:100%"><img style="width:100%;height:100%"></div>';document.body.append(aspect);
  check('percentage descendant box',aspect.firstElementChild.clientWidth===240&&aspect.firstElementChild.clientHeight===30&&aspect.querySelector('img').clientHeight===30);
  boxStyle.textContent+=' .pseudo-ratio{display:block;position:relative;min-width:240px;max-width:240px}.pseudo-ratio:before{content:"";display:block;padding-top:50%;opacity:0.3}.pseudo-ratio>div{position:absolute;top:0px;bottom:0px;width:100%}';
  const generated=document.createElement('x-pseudo-ratio');generated.className='pseudo-ratio';generated.innerHTML='<div><img style="width:100%;height:100%"></div>';document.body.append(generated);
  check('generated block ratio box',generated.clientWidth===240&&generated.clientHeight===120&&generated.firstElementChild.clientHeight===120);
  check('pseudo style does not leak',getComputedStyle(generated).opacity==='1');
  return checks.length?checks.join(', '):'ok';
})()
